INSERT INTO financial_checklist_items (category, title, description, sort_order, why_it_matters, external_resource_url, recommended_timing)
VALUES
  ('Investing for Kids', 'Open a custodial brokerage account (UTMA/UGMA)', 'A custodial account lets you invest stocks, ETFs, and bonds in your child''s name until they reach the age of majority.', 13, 'Gives your child a head start with real investments beyond education savings.', 'https://www.investopedia.com/terms/u/utma.asp', 'First 6 months'),
  ('Investing for Kids', 'Consider a Trump-era Roth IRA for your child', 'If your child has earned income (e.g., modeling, acting), you can open a custodial Roth IRA. The TCJA (Trump Tax Cuts & Jobs Act) kept favorable Roth rules.', 14, 'Tax-free growth for decades — even small contributions compound enormously for kids.', 'https://www.irs.gov/retirement-plans/roth-iras', 'When child has earned income'),
  ('Investing for Kids', 'Review Trump-era tax brackets for kiddie tax', 'The Tax Cuts and Jobs Act of 2017 changed how unearned income for children is taxed. Understand the "kiddie tax" rules for custodial accounts.', 15, 'Knowing the kiddie tax thresholds helps you plan contributions to UTMA/UGMA accounts wisely.', 'https://www.irs.gov/taxtopics/tc553', 'Before investing in custodial accounts'),
  ('Investing for Kids', 'Explore Opportunity Zone investments', 'Opportunity Zones, created by the 2017 Tax Cuts and Jobs Act, offer tax benefits for investing in designated low-income areas.', 16, 'Capital gains tax deferral and potential exclusion for long-term holds — a unique wealth-building tool.', 'https://www.irs.gov/credits-deductions/businesses/opportunity-zones', 'When you have capital gains to reinvest');
